class TtlCache:
  """Keeps values for `ttl` seconds."""

  def __init__(self, ttl, clock=time.monotonic):
    self.ttl = ttl
    self.clock = clock
    self.items = {}

  def get(self, key):
    hit = self.items.get(key)
    if hit is None:
      return None
    value, stored_at = hit
    if self.clock() - stored_at > self.ttl:
      del self.items[key]
      return None
    return value

  def put(self, key, value):
    self.items[key] = (value, self.clock())
